def _func_source(path: Path, func_name: str) -> str:
    src = path.read_text(encoding="utf-8")
    tree = ast.parse(src)
    lines = src.splitlines()
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == func_name:
            return "\n".join(lines[node.lineno - 1 : node.end_lineno])
    raise AssertionError(f"function {func_name} not found in {path}")


def test_bug_001_pending_pidless_not_graded_failed(tmp_path):
    (tmp_path / "run-00").mkdir()
    entry = {
        "index": 0, "description": "d", "repo": "r", "runner": "claude",
        "model": "opus", "channel": "clone", "mode": "A",
        "run_dir": str(tmp_path / "run-00"), "target_dir": str(tmp_path / "run-00" / "target"),
        "pid": None, "state": "PENDING", "started_at": "", "expect": {},
        "max_duration_s": 3600.0, "stream_path": str(tmp_path / "run-00" / "stream.ndjson"),
    }
    outcome = PR._collect_one_run_detached(entry, tmp_path)
    assert outcome.terminal_state != TerminalState.FAILED.value


