def test_bug_004_phase2_artifacts_resolve_to_phase2(tmp_path):
    q = tmp_path / "quality"
    q.mkdir()
    for name in ("EXPLORATION.md", "REQUIREMENTS.md", "CONTRACTS.md",
                 "COVERAGE_MATRIX.md", "COMPLETENESS_REPORT.md", "QUALITY.md",
                 "RUN_CODE_REVIEW.md"):
        (q / name).write_text("x\n", encoding="utf-8")
    inferred = ST._infer_phase_from_artifacts(tmp_path)
    assert inferred is not None and inferred["phase"] == 2


