def test_bug_005_pid0_malformed_started_at_not_active_forever():
    entry = {"pid": 0, "started_at": "not-a-real-timestamp", "provider": "anthropic"}
    assert IR._entry_is_active(entry) is False


def test_bug_006_council_response_trailing_bracket_parses():
    resp = (
        "Here is my review:\n"
        '[{"req_id": "REQ-001", "verdict": "supports", "reasoning": "ok"}]\n'
        "Note: REQ-001 relates to item [2] in the spec."
    )
    entries = CS.parse_member_response("claude-opus-4.7", resp, ["REQ-001"])
    assert [(e.req_id, e.verdict) for e in entries] == [("REQ-001", "supports")]


def test_bug_007_capture_phase_yn_no_false_completion(tmp_path):
    q = tmp_path / "quality"
    q.mkdir()
    for name in ("EXPLORATION.md", "REQUIREMENTS.md", "RUN_CODE_REVIEW.md",
                 "RUN_SPEC_AUDIT.md", "RUN_TDD_TESTS.md", "COMPLETENESS_REPORT.md"):
        (q / name).write_text("x\n", encoding="utf-8")
    yn = PR.capture_phase_yn("", q)
    assert [p for p in ("P3", "P4", "P5", "P6") if yn.get(p) == "Y"] == [], (
        "Phase-2-only tree must not mark P3-P6 complete")
